library(shiny)


# ============================================================
# DATA
# First two MCA dimensions
# ============================================================

coords &lt;- data.frame(

  variable = c(

    rep("Employment status", 3),
    rep("Sex", 2),
    rep("Nationality", 2),
    rep("Age", 4),
    rep("Access route", 2),
    rep("Family educational level", 3),
    rep("Admission grade", 10),
    rep("Degree subdiscipline", 22)

  ),


