    "Up to 15 hours/week",
    "15 or more hours/week",
    "Not working",

    # Sex
    "Male",
    "Female",

    # Nationality
    "Spanish",
    "Non-Spanish",

    # Age
    "Up to 18",
    "19–20",
    "21–24",
    "25 or older",

    # Access route
