# ============================================================
# STEM CLASSIFICATION
# ============================================================

stem_fields &lt;- c(

  "Biological and Earth Sciences",
  "Experimental Sciences and Mathematics",
  "Joint Programmes (Sciences)",
  "Architecture, Construction and Civil Engineering",
  "Industrial Technologies",
  "Information and Communication Technologies (ICT)",
  "Agriculture, Forestry and Fisheries",
  "Joint Programmes (Engineering)"

)


coords$stem &lt;- NA_character_


coords$stem[
  coords$type == "subfield"
] &lt;- ifelse(

  coords$label[
    coords$type == "subfield"
  ] %in% stem_fields,

  "STEM",
  "Non-STEM"

)



# ============================================================
# UI
# ============================================================

ui &lt;- fluidPage(

  tags$head(

    tags$style(

      HTML("

        body {

          font-family:
            system-ui,
            -apple-system,
            BlinkMacSystemFont,
            'Segoe UI',
            sans-serif;

          margin: 0;
          padding: 0;

        }


        .container-fluid {

          padding-left: 10px;
          padding-right: 10px;

        }


        .app-wrapper {

          max-width: 1180px;
          margin: 0 auto;

          padding:
            5px
            10px
            20px
            10px;

        }


        .plot-card {

          border: 1px solid #dddddd;
          border-radius: 9px;

          background: white;

          padding:
            10px
            12px
            5px
            12px;

          margin-bottom: 14px;

        }


        .control-panel {

          background: #f7f7f7;

          border-radius: 8px;

          padding:
            13px
            15px
            6px
            15px;

          margin-bottom: 15px;

        }


        .control-panel .form-group {

          margin-bottom: 9px;

        }


        .control-panel label.control-label {

          font-size: 12px;
          font-weight: 600;

        }


        .control-panel .radio-inline {

          font-size: 12px;

        }


        .selectize-control.multi
        .selectize-input {

          max-height: 78px;
          overflow-y: auto;

        }


        .clear-button {

          margin-top: 2px;
          font-size: 11px;

        }


        .plot-legend {

          display: flex;
          flex-wrap: wrap;

          gap: 20px;

          padding:
            2px
            5px
            8px
            5px;

          font-size: 11px;

          color: #666;

        }


        .legend-item {

          display: flex;
          align-items: center;

          gap: 6px;

        }


        .legend-circle {

          width: 10px;
          height: 10px;

          border-radius: 50%;

          display: inline-block;

          background: #bdbdbd;

        }


        .legend-square {

          width: 10px;
          height: 10px;

          display: inline-block;

          background: #bdbdbd;

        }


        .legend-blue {

          background: #4E79A7;

        }


        .legend-red {

          background: #C95D5D;

        }


        .information-row {

          margin-top: 3px;

        }


        .axis-description {

          font-size: 11px;

          line-height: 1.5;

          color: #666;

          padding: 8px 4px;

        }


        .selection-note {

          font-size: 11px;

          line-height: 1.5;

          color: #555;

          padding:
            8px
            12px;

          background: #fafafa;

          border-left:
            3px solid #C95D5D;

          margin-top: 8px;

          max-height: 150px;

          overflow-y: auto;

        }


        .method-note {

          font-size: 11px;

          line-height: 1.5;

          color: #666;

          margin-top: 12px;

          padding-top: 10px;

          border-top:
            1px solid #eeeeee;

        }


        /* ----------------------------------------------
           Hover behaviour inside SVG
           ---------------------------------------------- */

        .subfield-point {

          cursor: default;

        }


        .subfield-point .hover-label {

          opacity: 0;

          pointer-events: none;

          transition:
            opacity 0.12s ease;

        }


        .subfield-point:hover
        .hover-label {

          opacity: 1;

        }


        .subfield-point:hover
        .subfield-symbol {

          stroke: #555555;

          stroke-width: 2;

        }


        @media (max-width: 768px) {

          .app-wrapper {

            padding-left: 3px;
            padding-right: 3px;

          }


          .plot-card {

            padding: 4px;

          }

        }

      ")

    )

  ),



  div(

    class = "app-wrapper",


    # ========================================================
    # FACTORIAL SPACE
    # ========================================================

    fluidRow(

      column(

        width = 12,

        div(

          class = "plot-card",

          uiOutput("space"),


          # --------------------------------------------------
          # Legend
          # --------------------------------------------------

          div(

            class = "plot-legend",


            div(

              class = "legend-item",

              span(
                class =
                  "legend-circle legend-blue"
              ),

              span(
                "Selected variable categories"
              )

            ),


            div(

              class = "legend-item",

              span(
                class = "legend-circle"
              ),

              span("STEM subdiscipline")

            ),


            div(

              class = "legend-item",

              span(
                class = "legend-square"
              ),

              span("Non-STEM subdiscipline")

            ),


            div(

              class = "legend-item",

              span(
                class =
                  "legend-circle legend-red"
              ),

              span("Highlighted subdiscipline")

            )

          )

        )

      )

    ),



    # ========================================================
    # CONTROLS
    # ========================================================

    fluidRow(

      column(

        width = 12,

        div(

          class = "control-panel",

          fluidRow(


            # ------------------------------------------------
            # Layer
            # ------------------------------------------------

            column(

              width = 2,

              radioButtons(

                "layer",

                "Show",

                choices = c(

                  "Variables" =
                    "variables",

                  "Subdisciplines" =
                    "subfields",

                  "Both" =
                    "both"

                ),

                selected = "both",

                inline = TRUE

              )

            ),



            # ------------------------------------------------
            # Variable
            # ------------------------------------------------

            column(

              width = 2,

              conditionalPanel(

                condition =
                  "input.layer != 'subfields'",

                selectInput(

                  "variable",

                  "Active variable",

                  choices = c(

                    "Admission grade",
                    "Access route",
                    "Age",
                    "Employment status",
                    "Family educational level",
                    "Nationality",
                    "Sex"

                  ),

                  selected =
                    "Admission grade"

                )

              )

            ),



            # ------------------------------------------------
            # STEM filter
            # ------------------------------------------------

            column(

              width = 2,

              conditionalPanel(

                condition =
                  "input.layer != 'variables'",

                radioButtons(

                  "field_filter",

                  "Field type",

                  choices = c(

                    "All" =
                      "All",

                    "STEM" =
                      "STEM",

                    "Non-STEM" =
                      "Non-STEM"

                  ),

                  selected = "All",

                  inline = TRUE

                )

              )

            ),



            # ------------------------------------------------
            # Subdiscipline selector
            # ------------------------------------------------

            column(

              width = 5,

              conditionalPanel(

                condition =
                  "input.layer != 'variables'",

                selectizeInput(

                  "subfields",

                  "Highlight subdisciplines",

                  choices =
                    coords$label[
                      coords$type ==
                        "subfield"
                    ],

                  selected = c(

                    "Industrial Technologies",

                    "Information and Communication Technologies (ICT)"

                  ),

                  multiple = TRUE,

                  options = list(

                    plugins =
                      list(
                        "remove_button"
                      ),

                    placeholder =
                      "Select subdisciplines"

                  )

                ),


                actionButton(

                  "clear_subfields",

                  "Clear selection",

                  class =
                    "btn-default btn-sm clear-button"

                )

              )

            ),



            # ------------------------------------------------
            # Persistent labels
            # ------------------------------------------------

            column(

              width = 1,

              br(),

              checkboxInput(

                "labels",

                "Selected labels",

                value = TRUE

              )

            )

          )

        )

      )

    ),



    # ========================================================
    # INTERPRETATION
    # ========================================================

    fluidRow(

      class =
        "information-row",


      column(

        width = 6,

        div(

          class =
            "axis-description",

          HTML(

            "&lt;strong&gt;
            Axis 1 — Life-course position and
            institutionalised access pathway.
            &lt;/strong&gt;&lt;br&gt;

            Negative values are associated with
            earlier and academically linear entry
            trajectories; positive values with later,
            vocational and more constrained entry
            pathways.

            &lt;br&gt;&lt;br&gt;

            &lt;strong&gt;
            Axis 2 — Academic and institutional
            constraint gradient.
            &lt;/strong&gt;&lt;br&gt;

            This is a secondary dimension and should
            be interpreted more cautiously."

          )

        )

      ),



      column(

        width = 6,

        uiOutput(
          "selection_note"
        )

      )

    ),



    # ========================================================
    # METHODOLOGICAL NOTE
    # ========================================================

    div(

      class =
        "method-note",

      HTML(

        "&lt;strong&gt;How to read the space.&lt;/strong&gt;
        Proximity indicates association between categories
        and university-entry profiles.

        Degree subdisciplines are illustrative variables:
        they were projected after the factorial axes had
        been constructed and therefore do not contribute
        to the formation of the dimensions.

        &lt;br&gt;&lt;br&gt;

        &lt;strong&gt;STEM classification.&lt;/strong&gt;
        STEM includes scientific, technological,
        engineering and mathematical fields.
        Health-related fields are treated separately and
        are classified here as non-STEM, following the
        operational definition used in the study.

        &lt;br&gt;&lt;br&gt;

        &lt;strong&gt;Source:&lt;/strong&gt;
        Sánchez-Gelabert, A. & Simarro Rodríguez, C.
        (2026).
        &lt;em&gt;
        Gender and STEM: academic over-selection and
        stratified university entry
        &lt;/em&gt;.
        Research in Science & Technological Education."

      )

    )

  )

)



# ============================================================
# SERVER
# ============================================================

server &lt;- function(
  input,
  output,
  session
) {


  # ==========================================================
  # AVAILABLE SUBDISCIPLINES
  # ==========================================================

  available_subfields &lt;- reactive({


    d &lt;- coords[
      coords$type ==
        "subfield",
    ]


    if (
      is.null(input$field_filter) ||
      input$field_filter ==
        "All"
    ) {

      return(d$label)

    }


    d$label[
      d$stem ==
        input$field_filter
    ]

  })



  # ==========================================================
  # UPDATE SELECTOR WHEN STEM FILTER CHANGES
  # ==========================================================

  observeEvent(

    input$field_filter,

    {


      choices &lt;-
        available_subfields()


      current &lt;-
        input$subfields


      if (
        is.null(current)
      ) {

        current &lt;-
          character(0)

      }


      # Remove selections that do not belong
      # to the new filter

      current &lt;-
        intersect(
          current,
          choices
        )


      updateSelectizeInput(

        session,

        "subfields",

        choices =
          choices,

        selected =
          current,

        server =
          FALSE

      )

    }

  )



  # ==========================================================
  # CLEAR SELECTED SUBDISCIPLINES
  # ==========================================================

  observeEvent(

    input$clear_subfields,

    {

      updateSelectizeInput(

        session,

        "subfields",

        choices =
          available_subfields(),

        selected =
          character(0),

        server =
          FALSE

      )

    }

  )



  # ==========================================================
  # FACTORIAL SPACE
  # ==========================================================

  output$space &lt;- renderUI({


    # --------------------------------------------------------
    # Plot limits
    # --------------------------------------------------------

    if (
      input$layer ==
        "subfields"
    ) {

      xmin &lt;- -0.70
      xmax &lt;-  1.15

      ymin &lt;- -0.60
      ymax &lt;-  0.75

    } else {

      xmin &lt;- -0.80
      xmax &lt;-  2.25

      ymin &lt;- -2.20
      ymax &lt;-  0.80

    }



    # --------------------------------------------------------
    # SVG dimensions
    # --------------------------------------------------------

    svg_width  &lt;- 1000
    svg_height &lt;- 560

    left   &lt;- 85
    right  &lt;- 965

    top    &lt;- 38
    bottom &lt;- 485



    # --------------------------------------------------------
    # Coordinate transforms
    # --------------------------------------------------------

    sx &lt;- function(x) {

      left +

        (x - xmin) /
        (xmax - xmin) *

        (right - left)

    }


    sy &lt;- function(y) {

      bottom -

        (y - ymin) /
        (ymax - ymin) *

        (bottom - top)

    }



    # --------------------------------------------------------
    # HTML-safe strings
    # --------------------------------------------------------

    esc &lt;- function(x) {

      as.character(

        htmltools::htmlEscape(
          x
        )

      )

    }



    # ========================================================
    # AXES
    # ========================================================

    axis_html &lt;- ""


    if (
      xmin &lt;= 0 &&
      xmax &gt;= 0
    ) {

      axis_html &lt;- paste0(

        axis_html,

        '&lt;line
           x1="', sx(0), '"
           y1="', top, '"
           x2="', sx(0), '"
           y2="', bottom, '"
           stroke="#cccccc"
           stroke-width="1"/&gt;'

      )

    }


    if (
      ymin &lt;= 0 &&
      ymax &gt;= 0
    ) {

      axis_html &lt;- paste0(

        axis_html,

        '&lt;line
           x1="', left, '"
           y1="', sy(0), '"
           x2="', right, '"
           y2="', sy(0), '"
           stroke="#cccccc"
           stroke-width="1"/&gt;'

      )

    }



    # ========================================================
    # ACTIVE VARIABLE CATEGORIES
    # ========================================================

    variable_html &lt;- ""


    if (
      input$layer %in%
        c(
          "variables",
          "both"
        )
    ) {


      d &lt;- coords[

        coords$type ==
          "active" &

        coords$variable ==
          input$variable,

      ]


      variable_html &lt;- paste(

        vapply(

          seq_len(
            nrow(d)
          ),

          function(i) {


            px &lt;-
              sx(
                d$dim1[i]
              )


            py &lt;-
              sy(
                d$dim2[i]
              )


            if (
              d$dim1[i] &gt;
                1
            ) {

              tx &lt;-
                px - 11

              anchor &lt;-
                "end"

            } else {

              tx &lt;-
                px + 11

              anchor &lt;-
                "start"

            }


            label_html &lt;- ""


            if (
              isTRUE(
                input$labels
              )
            ) {

              label_html &lt;- paste0(

                '&lt;text
                   x="', tx, '"
                   y="', py - 9, '"
                   text-anchor="', anchor, '"
                   font-size="13"
                   fill="#333333"
                   style="
                     paint-order:stroke;
                     stroke:white;
                     stroke-width:3px;
                     stroke-linejoin:round;
                   "&gt;',

                esc(
                  d$label[i]
                ),

                '&lt;/text&gt;'

              )

            }


            paste0(

              '&lt;circle

                 cx="', px, '"
                 cy="', py, '"

                 r="7.5"

                 fill="#4E79A7"

                 stroke="white"

                 stroke-width="1.5"&gt;

                 &lt;title&gt;',

                 esc(
                   d$label[i]
                 ),

                 ' | Dim 1: ',

                 round(
                   d$dim1[i],
                   3
                 ),

                 ' | Dim 2: ',

                 round(
                   d$dim2[i],
                   3
                 ),

                 '&lt;/title&gt;

               &lt;/circle&gt;',

              label_html

            )

          },

          character(1)

        ),

        collapse = ""

      )

    }



    # ========================================================
    # SUBDISCIPLINES
    # ========================================================

    subfield_html &lt;- ""


    if (
      input$layer %in%
        c(
          "subfields",
          "both"
        )
    ) {


      d &lt;- coords[
        coords$type ==
          "subfield",
      ]


      # ------------------------------------------------------
      # Apply STEM / Non-STEM filter
      # ------------------------------------------------------

      if (

        !is.null(
          input$field_filter
        ) &&

        input$field_filter !=
          "All"

      ) {

        d &lt;- d[
          d$stem ==
            input$field_filter,
        ]

      }



      selected_subfields &lt;-
        input$subfields


      if (
        is.null(
          selected_subfields
        )
      ) {

        selected_subfields &lt;-
          character(0)

      }



      # ======================================================
      # UNSELECTED SUBDISCIPLINES
      # ======================================================

      unselected &lt;- d[
        !(
          d$label %in%
            selected_subfields
        ),
      ]


      unselected_html &lt;- ""


      if (
        nrow(unselected) &gt;
          0
      ) {


        unselected_html &lt;- paste(

          vapply(

            seq_len(
              nrow(
                unselected
              )
            ),

            function(i) {


              px &lt;-
                sx(
                  unselected$dim1[i]
                )


              py &lt;-
                sy(
                  unselected$dim2[i]
                )



              # Label position

              if (
                unselected$dim1[i] &gt;
                  0.50
              ) {

                tx &lt;-
                  px - 10

                anchor &lt;-
                  "end"

              } else {

                tx &lt;-
                  px + 10

                anchor &lt;-
                  "start"

              }



              # ----------------------------------------------
              # STEM = circle
              # Non-STEM = square
              # ----------------------------------------------

              if (
                unselected$stem[i] ==
                  "STEM"
              ) {

                symbol &lt;- paste0(

                  '&lt;circle
                     class="subfield-symbol"

                     cx="', px, '"
                     cy="', py, '"

                     r="5.5"

                     fill="#bdbdbd"

                     stroke="white"

                     stroke-width="1"/&gt;'

                )

              } else {


                symbol &lt;- paste0(

                  '&lt;rect
                     class="subfield-symbol"

                     x="',
                     px - 5,
                     '"

                     y="',
                     py - 5,
                     '"

                     width="10"

                     height="10"

                     rx="1"

                     fill="#bdbdbd"

                     stroke="white"

                     stroke-width="1"/&gt;'

                )

              }



              # ----------------------------------------------
              # Hover group
              # ----------------------------------------------

              paste0(

                '&lt;g class="subfield-point"&gt;',

                symbol,


                '&lt;text

                   class="hover-label"

                   x="', tx, '"

                   y="',
                   py - 9,
                   '"

                   text-anchor="',
                   anchor,
                   '"

                   font-size="12"

                   font-weight="500"

                   fill="#666666"

                   style="
                     paint-order:stroke;
                     stroke:white;
                     stroke-width:4px;
                     stroke-linejoin:round;
                   "&gt;',

                esc(
                  unselected$label[i]
                ),

                '&lt;/text&gt;',


                '&lt;title&gt;',

                esc(
                  unselected$label[i]
                ),

                ' · ',

                unselected$stem[i],

                ' | Dim 1: ',

                round(
                  unselected$dim1[i],
                  3
                ),

                ' | Dim 2: ',

                round(
                  unselected$dim2[i],
                  3
                ),

                '&lt;/title&gt;',


                '&lt;/g&gt;'

              )

            },

            character(1)

          ),

          collapse = ""

        )

      }



      # ======================================================
      # SELECTED SUBDISCIPLINES
      # ======================================================

      selected &lt;- d[
        d$label %in%
          selected_subfields,
      ]


      selected_html &lt;- ""


      if (
        nrow(selected) &gt;
          0
      ) {


        selected_html &lt;- paste(

          vapply(

            seq_len(
              nrow(
                selected
              )
            ),

            function(i) {


              px &lt;-
                sx(
                  selected$dim1[i]
                )


              py &lt;-
                sy(
                  selected$dim2[i]
                )



              if (
                selected$dim1[i] &gt;
                  0.50
              ) {

                tx &lt;-
                  px - 11

                anchor &lt;-
                  "end"

              } else {

                tx &lt;-
                  px + 11

                anchor &lt;-
                  "start"

              }



              # ----------------------------------------------
              # Persistent selected label
              # ----------------------------------------------

              persistent_label &lt;- ""


              if (
                isTRUE(
                  input$labels
                )
              ) {


                persistent_label &lt;- paste0(

                  '&lt;text

                     x="',
                     tx,
                     '"

                     y="',
                     py - 10,
                     '"

                     text-anchor="',
                     anchor,
                     '"

                     font-size="12"

                     font-weight="600"

                     fill="#333333"

                     style="
                       paint-order:stroke;
                       stroke:white;
                       stroke-width:4px;
                       stroke-linejoin:round;
                     "&gt;',

                  esc(
                    selected$label[i]
                  ),

                  '&lt;/text&gt;'

                )

              }



              # ----------------------------------------------
              # STEM = circle
              # Non-STEM = square
              # ----------------------------------------------

              if (
                selected$stem[i] ==
                  "STEM"
              ) {


                symbol &lt;- paste0(

                  '&lt;circle

                     class="subfield-symbol"

                     cx="',
                     px,
                     '"

                     cy="',
                     py,
                     '"

                     r="8"

                     fill="#C95D5D"

                     stroke="white"

                     stroke-width="1.7"/&gt;'

                )


              } else {


                symbol &lt;- paste0(

                  '&lt;rect

                     class="subfield-symbol"

                     x="',
                     px - 7,
                     '"

                     y="',
                     py - 7,
                     '"

                     width="14"

                     height="14"

                     rx="1.5"

                     fill="#C95D5D"

                     stroke="white"

                     stroke-width="1.7"/&gt;'

                )

              }



              # ----------------------------------------------
              # Hover label
              # Always exists.
              # Useful when persistent labels are disabled.
              # ----------------------------------------------

              paste0(

                '&lt;g class="subfield-point"&gt;',

                symbol,


                '&lt;text

                   class="hover-label"

                   x="',
                   tx,
                   '"

                   y="',
                   py - 10,
                   '"

                   text-anchor="',
                   anchor,
                   '"

                   font-size="12"

                   font-weight="600"

                   fill="#666666"

                   style="
                     paint-order:stroke;
                     stroke:white;
                     stroke-width:4px;
                     stroke-linejoin:round;
                   "&gt;',

                esc(
                  selected$label[i]
                ),

                '&lt;/text&gt;',


                '&lt;title&gt;',

                esc(
                  selected$label[i]
                ),

                ' · ',

                selected$stem[i],

                ' | Dim 1: ',

                round(
                  selected$dim1[i],
                  3
                ),

                ' | Dim 2: ',

                round(
                  selected$dim2[i],
                  3
                ),

                '&lt;/title&gt;',


                '&lt;/g&gt;',


                persistent_label

              )

            },

            character(1)

          ),

          collapse = ""

        )

      }



      subfield_html &lt;- paste0(

        unselected_html,

        selected_html

      )

    }



    # ========================================================
    # ZOOM NOTE
    # ========================================================

    zoom_label &lt;- ""


    if (
      input$layer ==
        "subfields"
    ) {

      zoom_label &lt;- paste0(

        '&lt;text

           x="',
           right,
           '"

           y="23"

           text-anchor="end"

           font-size="11"

           fill="#777777"&gt;

           Zoomed subdiscipline view

         &lt;/text&gt;'

      )

    }



    # ========================================================
    # FIELD FILTER LABEL
    # ========================================================

    filter_label &lt;- ""


    if (
      input$layer %in%
        c(
          "subfields",
          "both"
        ) &&
      !is.null(
        input$field_filter
      )
    ) {

      filter_label &lt;- paste0(

        '&lt;text

           x="',
           left,
           '"

           y="23"

           text-anchor="start"

           font-size="11"

           font-weight="600"

           fill="#777777"&gt;',

        esc(
          paste0(
            "Fields: ",
            input$field_filter
          )
        ),

        '&lt;/text&gt;'

      )

    }



    # ========================================================
    # SVG
    # ========================================================

    html &lt;- paste0(

      '&lt;svg

         viewBox="0 0 ',
         svg_width,
         ' ',
         svg_height,
         '"

         preserveAspectRatio=
           "xMidYMid meet"

         style="
           width:100%;
           height:auto;
           display:block;
         "&gt;',



      # ------------------------------------------------------
      # Background
      # ------------------------------------------------------

      '&lt;rect

         x="',
         left,
         '"

         y="',
         top,
         '"

         width="',
         right - left,
         '"

         height="',
         bottom - top,
         '"

         fill="#ffffff"

         stroke="#eeeeee"/&gt;',



      axis_html,

      variable_html,

      subfield_html,

      filter_label,

      zoom_label,



      # ------------------------------------------------------
      # Axis 1 interpretation
      # ------------------------------------------------------

      '&lt;text

         x="',
         left,
         '"

         y="515"

         text-anchor="start"

         font-size="11"

         fill="#777777"&gt;

         ← Academic / linear

       &lt;/text&gt;',



      '&lt;text

         x="',
         right,
         '"

         y="515"

         text-anchor="end"

         font-size="11"

         fill="#777777"&gt;

         Vocational / delayed →

       &lt;/text&gt;',



      '&lt;text

         x="525"

         y="545"

         text-anchor="middle"

         font-size="12"

         font-weight="600"

         fill="#555555"&gt;

         Axis 1 — Life-course position and
         institutionalised access pathway

       &lt;/text&gt;',



      # ------------------------------------------------------
      # Axis 2
      # ------------------------------------------------------

      '&lt;text

         x="25"

         y="260"

         transform="
           rotate(-90 25 260)
         "

         text-anchor="middle"

         font-size="12"

         font-weight="600"

         fill="#555555"&gt;

         Axis 2 — Academic and institutional
         constraint gradient

       &lt;/text&gt;',


      '&lt;/svg&gt;'

    )


    HTML(
      html
    )

  })



  # ==========================================================
  # SELECTED SUBDISCIPLINE SUMMARY
  # ==========================================================

  output$selection_note &lt;- renderUI({


    if (

      input$layer ==
        "variables" ||

      is.null(
        input$subfields
      ) ||

      length(
        input$subfields
      ) ==
        0

    ) {

      return(
        NULL
      )

    }



    d &lt;- coords[

      coords$type ==
        "subfield" &

      coords$label %in%
        input$subfields,

    ]



    if (
      nrow(d) ==
        0
    ) {

      return(
        NULL
      )

    }



    lines &lt;- vapply(

      seq_len(
        nrow(d)
      ),

      function(i) {

        paste0(

          "&lt;strong&gt;",

          htmltools::htmlEscape(
            d$label[i]
          ),

          "&lt;/strong&gt;",

          " · ",

          d$stem[i],

          " &nbsp; ",

          "Dim 1 = ",

          sprintf(
            "%.3f",
            d$dim1[i]
          ),

          " · Dim 2 = ",

          sprintf(
            "%.3f",
            d$dim2[i]
          )

        )

      },

      character(1)

    )



    div(

      class =
        "selection-note",

      HTML(

        paste(
          lines,
          collapse = "&lt;br&gt;"
        )

      )

    )

  })

}



